const citas =
  $input
    .all()
    .map(item => item.json)
    .filter(cita => {
      const inicio =
        new Date(
          cita.inicio_google ?? ''
        );

      return (
        String(
          cita.cita_id ?? ''
        ).trim() !== '' &&
        !Number.isNaN(
          inicio.getTime()
        ) &&
        inicio.getTime() >=
          Date.now()
      );
    })
    .sort((a, b) => {
      return (
        new Date(
          a.inicio_google
        ).getTime() -
        new Date(
          b.inicio_google
        ).getTime()
      );
    });

const obtenerFechaHoraGuatemala = iso => {
  const fecha = new Date(iso);

  const partes =
    new Intl.DateTimeFormat(
      'en-US',
      {
        timeZone:
          'America/Guatemala',
        year:
          'numeric',
        month:
          '2-digit',
        day:
          '2-digit',
        hour:
          '2-digit',
        minute:
          '2-digit',
        hourCycle:
          'h23',
      }
    ).formatToParts(fecha);

  const valor = tipo =>
    partes.find(
      parte =>
        parte.type === tipo
    )?.value ?? '';

  return {
    fecha_local:
      `${valor('year')}-${valor('month')}-${valor('day')}`,

    hora_local:
      `${valor('hour')}:${valor('minute')}`,
  };
};

const pacienteId =
  String(
    citas[0]?.paciente_id ??
    $('resolver_paciente_consulta_citas_agenda_dz')
      .first()
      .json
      .paciente_id ??
    ''
  ).trim();

return [
  {
    json: {
      paciente_id:
        pacienteId,

      tiene_citas_futuras:
        citas.length > 0,

      citas_futuras_total:
        citas.length,

      citas_futuras:
        citas.map(cita => {
          const horario =
            obtenerFechaHoraGuatemala(
              cita.inicio_google
            );

          return {
            cita_id:
              cita.cita_id,

            inicio_google:
              cita.inicio_google,

            fin_google:
              cita.fin_google ?? null,

            fecha_local:
              horario.fecha_local,

            hora_local:
              horario.hora_local,

            clinica_id:
              cita.clinica_id ?? null,

            procedimiento_id:
              cita.procedimiento_id ?? null,

            nombre_procedimiento:
              cita.nombre_procedimiento ?? null,

            doctor_nombre:
              cita.doctor_nombre ?? null,

            profesional_id:
              cita.profesional_id ?? null,

            silla_id:
              cita.silla_id ?? null,

            nombre_silla:
              cita.nombre_silla ?? null,

            estado_confirmacion:
              cita.estado_confirmacion ?? null,
          };
        }),
    },
  },
];
